// The server's shapes, from its OpenAPI (schema.d.ts is generated by
// `npm run types`; never edited by hand). Where the server types a field as
// a free object (Dict[str, Any]) the narrower shape the web app reads is
// written here, next to the generated one, and named after the Python that
// makes it.
import type { FormRow, FormTab } from "@bam/ui";
import type { components } from "./schema";

type Sch = components["schemas"];

export type Pt = [number, number];
export type Loop = Pt[];
export type Issue = Sch["IssueOut"];
export type Layer = Sch["LayerOut"];
export type MeshBody = Sch["MeshOut"];
export type Frames = Sch["FramesOut"];
export type Guides = Sch["GuidesOut"];
export type TargetIn = Sch["TargetIn"];
export type TagSpecIn = Sch["TagSpecIn"];

/** plan/mesh.top: {colour: [polygon = [outer loop, hole loops...]]} */
export type TopView = Partial<Record<"body" | "white" | "black", Loop[][]>>;

/** TagPlanOut plus the two optional extras the Studio asks for. */
export type TagPlan = Sch["TagPlanOut"] & { top?: TopView };

/** core.markers.TagSpec.to_dict() as built (TagPlan.marker). */
export interface MarkerAsBuilt {
  dictionary: string;
  marker_id: number;
  marker_length_m: number;
  layout: "single" | "grid" | "charuco";
  rows?: number;
  cols?: number;
  ids?: number[];
  square_length_m?: number;
  quiet_modules?: number;
  [k: string]: unknown;
}

/** A TagSpec as the scene keeps it (plan/spec.TagSpec.to_dict()). */
export interface TagSpec {
  schema: string;
  settings: Settings;
  numbers: Record<string, number>;
  target: Target;
  name: string;
  key: string;
}

export type Settings = Record<string, unknown> & {
  layout?: string;
  label?: Record<string, unknown>;
};

/** plan/target.Target.to_dict() (ARCHITECTURE 5.1, PLAN section 8). */
export interface Target {
  kind: string;
  w_mm: number;
  h_mm: number;
  loops_mm: Loop[];
  has_body: boolean;
  z_sign: number;
  x_ref: Pt | null;
  body_mm: { u0: number; v0: number; u1: number; v1: number; z0: number; z1: number; measured?: boolean; depth?: number } | null;
  body_loops_mm: Loop[] | null;
  face_loops_mm: Loop[] | null;
  name: string;
  [k: string]: unknown;
}

/** scene/model.SceneTag.to_dict() (ARCHITECTURE 5.5) with its plan. */
export interface SceneTag {
  name: string;
  uid: string;
  spec: TagSpec;
  x_mm: number;
  y_mm: number;
  rotation_deg: number;
  pose: number[];
  locked: boolean;
  hidden: boolean;
  plan: TagPlan | null;
  /** where it is in the design file (scene/design.compile, M8a) */
  source?: TagSource;
  /** its full pose (a row-major 4x4, mm) when it is not z-up at z 0 */
  pose_3d?: number[];
}

/** A compiled tag's place in the design file (GET /api/scene's `source`). */
export interface TagSource {
  feature: number;
  entry: number | null;
  ref: string;
  shape: string | null;
  sketch: string | null;
  body: string | null;
  face: string | null;
  normal: [number, number, number];
  hinge: [Pt, Pt] | null;
  hinge_xy?: [Pt, Pt];
  over?: string;
}

/** GET /api/design (server/design_api.Design.info). */
export interface DesignInfo {
  path: string | null;
  state: "memory" | "ok" | "broken" | "missing";
  text: string;
  hash: string | null;
  revision: number;
  error: { line: number | null; col: number | null; message: string; text?: string } | null;
  issues: Issue[];
  schema: string;
}

export interface SceneDoc {
  schema: string;
  units: string;
  name: string;
  tags: SceneTag[];
  ledger: unknown;
  overrides: Record<string, number>;
  presets_used: string[];
  /** scene/checks.py (GET /api/scene?plans=1): overlapping tags, ... */
  issues?: SceneIssue[];
}

/** A message about the scene as a whole (scene/checks.scene_issues). */
export interface SceneIssue {
  tags: string[];
  level: "error" | "warn" | "info";
  kind: string;
  text: string;
}

/** plan/fields.py: one row of the inspector's contract (GET /api/form, bam.form/1). */
export interface FormField extends FormRow {
  group: string;
  default: unknown;
  intent?: "3d" | "2d" | "both";
  label_2d?: string;
  on_3d?: string;
  choices_by_layout?: Record<string, { value: string | number; label: string }[]>;
  choices_when?: { when: Record<string, unknown>; choices: { value: string | number; label: string }[] }[];
  icons_by_layout?: Record<string, Record<string, string>>;
  min_exclusive?: number;
  min_abs?: number | null;
  warn_below?: number;
  layouts?: string[];
  of?: string[];
  axes?: string[];
  min_mm?: number;
  max_mm?: number;
  min_cap?: number;
  rule?: number;
}

export interface FormDoc {
  schema: string;
  contract?: string;
  fields: FormField[];
  tabs: FormTab[];
  outside: string[];
  groups: string[];
  layouts: string[];
  rules: Record<string, number>;
}

export interface PaletteEntry {
  key: string;
  title: string;
  target: Target;
}

export interface Dictionary {
  name: string;
  bits: number;
  capacity: number;
  family: string;
  modules: number;
}

/** core.presets' preset shape (bam_aruco_presets/1). */
export interface Preset {
  name: string;
  profile: Record<string, unknown>;
  cells: Record<string, unknown>;
  tag: Record<string, unknown>;
  label: Record<string, unknown>;
}

export interface PresetItem {
  name: string;
  kind: "builtin" | "user";
  preset: Preset;
  /** its profile's kind (M6a): a 3D printer or a sticker printer */
  made_by?: "print3d" | "sticker";
}

/** GET /api/presets' collections (M6a): 3D printers, sticker printers. */
export interface PresetCollection { id: string; title: string; icon: string; names: string[] }

/** server/library.py's card (REF aruco_preset_library.Library._card). */
export interface LibraryCard {
  id: string;
  name: string;
  kind: "builtin" | "user" | "prusa" | "document" | "printer" | "sticker";
  in: string[];
  editable: boolean;
  subtitle: string;
  nozzle?: number;
  line?: number;
  layer?: number | null;
  dictionary?: string;
  mode?: string;
  mode_words?: string;
  profile?: string;
  cells?: string;
  thumb: string;
  used: number;
  info: [string, [string, string][]][];
  recent: number | null;
  differs: string;
  preset: Preset | null;
  unreadable?: boolean;
  /** a Printers card (M8c): the physical printer, its fitting prints */
  printer?: Record<string, any>;
  choices?: PrinterChoice[];
  default?: string | null;
  current?: boolean;
  host_kind?: string;
  technology?: string;
}

/** A print preset that fits a physical printer (a Printers card's choice). */
export interface PrinterChoice { id: string; name: string; fits: string; line: number; layer: number; first_layer: number; nozzle: number; aruco: boolean; current: boolean }

/** GET /api/prusa/printers (server/prusa_api.py). */
export interface PrusaPrinters {
  dir: string | null;
  found: boolean;
  printers: PrusaPrinter[];
  current: { physical: string | null; printer: string | null; print: string | null } | null;
  notes: string[];
  revision: number;
}
export interface PrusaPrinter {
  name: string;
  technology: string;
  host_kind: string;
  presets: string[];
  preset: string;
  printer: { preset: string; nozzle_mm: number; model: string; variant: string; bed_mm: [number, number]; [k: string]: unknown };
  prints: { name: string; fits: string; user: boolean; aruco: boolean; line_mm: number; layer_mm: number; first_layer_mm: number; nozzle_mm: number; current: boolean }[];
  current: boolean;
  current_print: string | null;
}
export interface SendBody { printer?: string; print?: string; white_slot?: number; black_slot?: number; open: boolean }
export interface SendAnswer {
  project: string; parts: number | any[]; beds: number | any[]; skipped: any[]; rejected: any[]; warnings: string[]; opened: boolean;
  printer: { physical: string | null; preset: string }; print: string; filament: string; bed_mm: [number, number];
}

/** GET /api/scene/sheet.json (arucostudio.sheet/1). */
export interface SheetJson {
  schema: string; page: string; page_mm: [number, number]; pages: number; mode: string; cuts: number;
  stickers: { key: string; name: string; made_by: string; ids: number[]; page: number; x_mm: number; y_mm: number; w_mm: number; h_mm: number; rotation: number; caption: string | string[] }[];
  shelves: { page: number; y_mm: number; h_mm: number; keys: string[] }[];
  rejected: { key?: string; name?: string; reason?: string; [k: string]: unknown }[];
  ruler: { mm_bar: number[]; in_bar: number[]; top: number };
  [k: string]: unknown;
}

/** GET /api/prusa/stale: a tag whose preset's PrusaSlicer profile changed. */
export interface StaleInfo { tag: string; preset: string; field: string; level: string; text: string; was: unknown; now: unknown; apply: string }

export interface LibraryState {
  title: string;
  collections: { id: string; name: string; icon: string; count: number }[];
  cards: LibraryCard[];
  selected: string | null;
  schema: [string, string, string, [string, string][] | null][];
  /** the range a preset keeps each number in (server/library.LIMITS) */
  limits?: Record<string, [number, number]>;
  notes: string[];
  dialog: boolean;
}

/** core.numbering's IdsPlan row (scene/ids.renumber). */
export interface RenumberRow {
  tag: string;
  name: string;
  final: number;
  ids?: number[];
  [k: string]: unknown;
}

export interface RenumberReport {
  rows: RenumberRow[];
  changed: { tag: string; from: number; to: number }[];
  duplicates: unknown;
  warnings: string[];
  errors: string[];
  ok: boolean;
}

/** verify/report.verify_plan. */
export interface VerifyReport {
  ok: boolean;
  errors?: string[];
  ids_expected: number[];
  ids_read: number[];
  missing?: number[];
  extra?: number[];
  corner_err_px?: number;
  corner_err_mm?: number;
  pnp_err_mm?: number;
  pnp_err_deg?: number;
  charuco_corners?: number;
  charuco_read?: number;
  image_png?: string;
  [k: string]: unknown;
}
